CREATE TABLE IF NOT EXISTS capital_snapshot (id INT AUTO_INCREMENT PRIMARY KEY, `date` DATE NOT NULL, external_balance DECIMAL(14, 2) NOT NULL, planned_contribution DECIMAL(14, 2) NOT NULL, created_at DATETIME(6) NOT NULL);
